'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-sfill-nan';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';


// MAIN //

/**
* Replaces elements in a one-dimensional single-precision floating-point ndarray equal to `NaN` with a specified scalar constant.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} input ndarray
*
* @example
* import Float32Vector from '@stdlib/ndarray-vector-float32';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = new Float32Vector( [ NaN, -2.0, 3.0, NaN, 4.0, -6.0 ] );
*
* var alpha = scalar2ndarray( 0.0, {
*     'dtype': 'float32'
* });
*
* var out = sfillNaN( [ x, alpha ] );
* // returns <ndarray>[ 0.0, -2.0, 3.0, 0.0, 4.0, -6.0 ]
*/
function sfillNaN( arrays ) {
	var alpha;
	var x;

	x = arrays[ 0 ];
	alpha = ndarraylike2scalar( arrays[ 1 ] );
	strided( numelDimension( x, 0 ), alpha, getData( x ), getStride( x, 0 ), getOffset( x ) ); // eslint-disable-line max-len
	return x;
}


// EXPORTS //

export default sfillNaN;
